  push!(__initialization_eqs, carcass_y ~ 0)

  ### Assertions
  __assertions = []

  ### Equations
  push!(__eqs, road.inputs.x ~ getindex(getproperty(wheel_center, :r_0), 1))
  push!(__eqs, road.inputs.y ~ getindex(getproperty(wheel_center, :r_0), 2))
  push!(__eqs, z_w ~ getindex(getproperty(wheel_center, :r_0), 3) - road.outputs.z)
  push!(__eqs, rho ~ max(0, UNLOADED_RADIUS - z_w))
  push!(__eqs, loaded_radius ~ UNLOADED_RADIUS - rho)
  push!(__eqs, Fz ~ ifelse(rho > 0, max(0, VERTICAL_STIFFNESS * rho - VERTICAL_DAMPING * ModelingToolkit.D_nounits(z_w)), 0))
  push!(__eqs, Re ~ UNLOADED_RADIUS - FREFF * rho)
  push!(__eqs, omega ~ ModelingToolkit.D_nounits(spline.phi))
  push!(__eqs, sin_gamma ~ side * getindex(getproperty(wheel_center, :R), 2, 3))
  push!(__eqs, cos_gamma ~ sqrt(max(1 - sin_gamma ^ 2, 1e-8)))
  push!(__eqs, V_x ~ (ModelingToolkit.D_nounits(getindex(getproperty(wheel_center, :r_0), 1)) * getindex(getproperty(wheel_center, :R), 2, 2) - ModelingToolkit.D_nounits(getindex(getproperty(wheel_center, :r_0), 2)) * getindex(getproperty(wheel_center, :R), 2, 1)) / cos_gamma)
  push!(__eqs, V_y ~ side * (ModelingToolkit.D_nounits(getindex(getproperty(wheel_center, :r_0), 1)) * getindex(getproperty(wheel_center, :R), 2, 1) + ModelingToolkit.D_nounits(getindex(getproperty(wheel_center, :r_0), 2)) * getindex(getproperty(wheel_center, :R), 2, 2)) / cos_gamma)
  push!(__eqs, V_roll ~ omega * Re)
  push!(__eqs, drive_speed ~ V_roll - V_x)
  push!(__eqs, camber_slip ~ (CAMBER_GAIN + CAMBER_GAIN_LOAD * dfz) * sin_gamma)
  push!(__eqs, side_speed ~ -V_y + abs(V_roll) * (camber_slip + LATERAL_SLIP_BIAS))
  push!(__eqs, kappa ~ drive_speed / max(abs(V_x), 1.0))
  push!(__eqs, alpha ~ atan(V_y / max(abs(V_x), 1.0)))
  push!(__eqs, fit_load ~ min(max(Fz, FIT_LOAD_MIN), FIT_LOAD_MAX))
  push!(__eqs, dfz ~ fit_load / FNOMIN - 1)
  push!(__eqs, rolling_fraction ~ min(max((abs(V_x) - RESTART_SPEED_MAX) / (ROLLING_SPEED_MIN - RESTART_SPEED_MAX), 0), 1))
  push!(__eqs, rolling_weight ~ rolling_fraction ^ 2 * (3 - 2 * rolling_fraction))
  push!(__eqs, kx ~ K_X_NOM * exp(K_X_LOAD * dfz + K_X_DIRECTION * tanh(drive_speed / 1.0)))
  push!(__eqs, ky ~ K_Y_NOM * exp(K_Y_LOAD * dfz + K_Y_CAMBER * abs(sin_gamma)) * (K_Y_RESTART_RATIO + (1 - K_Y_RESTART_RATIO) * rolling_weight))
  push!(__eqs, mu_ax ~ MU_X_NOM * exp(MU_X_LOAD * dfz + MU_X_CAMBER * sin_gamma ^ 2))
  push!(__eqs, mu_ay ~ MU_Y_NOM * exp(MU_Y_LOAD * dfz + MU_Y_CAMBER * sin_gamma ^ 2 + MU_Y_DIRECTION * tanh(side_speed / max(0.05 * abs(V_roll), 0.05))) * (MU_Y_RESTART_RATIO + (1 - MU_Y_RESTART_RATIO) * rolling_weight))
  push!(__eqs, a ~ CONTACT_HALF_LENGTH * sqrt(fit_load / FNOMIN))
  push!(__eqs, sigma_x ~ fit_load * kx / LONGITUDINAL_STIFFNESS)
  push!(__eqs, sigma_y ~ fit_load * ky / (LATERAL_STIFFNESS * exp(LATERAL_STIFFNESS_LOAD * dfz)))
  push!(__eqs, sx ~ (total_x - carcass_x) / a)
  push!(__eqs, sy ~ (total_y - carcass_y) / a)
  push!(__eqs, demand ~ sqrt((kx * sx / mu_ax) ^ 2 + (ky * sy / mu_ay) ^ 2 + 1e-24))
  push!(__eqs, adhesion ~ max(0, 1 - demand / 3))
  push!(__eqs, sliding_weight ~ (1 - adhesion) ^ 2 * (1 + 2 * adhesion))
  push!(__eqs, sliding_norm ~ sqrt((mu_ax * sx) ^ 2 + (mu_ay * sy) ^ 2 + 1e-24))
  push!(__eqs, slide_fx ~ mu_ax ^ 2 * sx / sliding_norm)
  push!(__eqs, slide_fy ~ mu_ay ^ 2 * sy / sliding_norm)
  push!(__eqs, normalized_fx ~ kx * sx * adhesion ^ 2 + slide_fx * sliding_weight)
  push!(__eqs, lateral_efficiency ~ 1 - COMBINED_Y_LOSS * max(0, 1 - abs(ky * sy / mu_ay) / 3) * (kx * sx / mu_ax) ^ 2 / (1 + (kx * sx / mu_ax) ^ 2))
  push!(__eqs, normalized_fy ~ lateral_efficiency * (ky * sy * adhesion ^ 2 + slide_fy * sliding_weight))
  push!(__eqs, Fx ~ Fz * normalized_fx)
  push!(__eqs, Fy ~ Fz * normalized_fy)
  push!(__eqs, trail_slip ~ -sy + camber_slip + LATERAL_SLIP_BIAS)
  push!(__eqs, moment_demand ~ sqrt((trail_slip + camber_slip) ^ 2 + sx ^ 2 + 1e-24))
  push!(__eqs, arm_argument ~ MZ_TRAIL_RATE * exp((K_Y_LOAD - MU_Y_LOAD) * dfz) * moment_demand)
  push!(__eqs, pneumatic_moment ~ ifelse(MZ_TRAIL_RATE > 0, Fz * MZ_TRAIL_SCALE * CONTACT_HALF_LENGTH * K_Y_NOM / 3 * exp(MZ_STIFFNESS_LOAD * dfz + MU_Y_CAMBER * sin_gamma ^ 2) * trail_slip * (1 - MZ_SLIDING_ARM * arm_argument ^ 2 / sqrt(1 + arm_argument ^ 2)) / (1 + arm_argument ^ 2), MZ_TRAIL_SCALE * a * Fz * (ky * sy * adhesion ^ 2 * (1 - 4 * adhesion / 3) - 3 * slide_fy * (adhesion * (1 - adhesion)) ^ 2)))
  push!(__eqs, camber_moment ~ UNLOADED_RADIUS * Fz * (MZ_CAMBER + MZ_CAMBER_LOAD * dfz) * sin_gamma / sqrt(1 + (MZ_RESIDUAL_RATE * moment_demand) ^ 2))
  push!(__eqs, Mz ~ (pneumatic_moment + camber_moment) * V_roll / sqrt(V_roll ^ 2 + 0.0001))
  push!(__eqs, transport ~ max(abs(V_roll), sqrt((kx * drive_speed / mu_ax) ^ 2 + (ky * side_speed / mu_ay) ^ 2 + 1e-24) / ifelse(MZ_TRAIL_RATE > 0, 12, 3)))
  push!(__eqs, ModelingToolkit.D_nounits(total_x) ~ ifelse(Fz > 0, drive_speed - transport * sx, -total_x / CARCASS_TIME_CONSTANT))
  push!(__eqs, ModelingToolkit.D_nounits(total_y) ~ ifelse(Fz > 0, side_speed - transport * sy, -total_y / CARCASS_TIME_CONSTANT))
  push!(__eqs, ModelingToolkit.D_nounits(carcass_x) ~ (ifelse(Fz > 0, max(0, sigma_x - a) * normalized_fx / kx, 0) - carcass_x) / CARCASS_TIME_CONSTANT)
  push!(__eqs, ModelingToolkit.D_nounits(carcass_y) ~ (ifelse(Fz > 0, max(0, sigma_y - a) * normalized_fy / ky, 0) - carcass_y) / CARCASS_TIME_CONSTANT)
  push!(__eqs, fx_world ~ (Fx * getindex(getproperty(wheel_center, :R), 2, 2) + side * Fy * getindex(getproperty(wheel_center, :R), 2, 1)) / cos_gamma)
  push!(__eqs, fy_world ~ (side * Fy * getindex(getproperty(wheel_center, :R), 2, 2) - Fx * getindex(getproperty(wheel_center, :R), 2, 1)) / cos_gamma)
  push!(__eqs, wheel_center.f ~ -wheel_center.R * [fx_world, fy_world, Fz])
  push!(__eqs, wheel_center.tau ~ -wheel_center.R * [loaded_radius * fy_world, -loaded_radius * fx_world, side * Mz])
  push!(__eqs, spline.tau ~ Fx * loaded_radius)
  push!(__eqs, outputs.slip ~ kappa)
  push!(__eqs, outputs.Fx ~ Fx)
  push!(__eqs, outputs.Fy ~ Fy)
  push!(__eqs, outputs.Fz ~ Fz)
  push!(__eqs, outputs.alpha ~ alpha)
  push!(__eqs, outputs.omega ~ omega)
  push!(__eqs, outputs.Re ~ Re)

  # Return completely constructed System
  return System(__eqs, ModelingToolkit.t_nounits, __vars, __params; systems=__systems, initial_conditions=__initial_conditions, guesses=__guesses, name, initialization_eqs=__initialization_eqs, bindings=__bindings, assertions=__assertions)
end
export TireBrush
